import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  findJobById,
  findJobByKey,
  insertJob,
  listJobs,
  readHeartbeat,
  toJob,
  type JobRow,
} from './jobs.ts';
import { validateSubmission, type FieldError } from './validation.ts';

/** A worker heartbeat older than this means the worker is down. */
const WORKER_STALE_MS = 3_000;
/** Large enough for a 1000-character input with JSON escapes plus the other fields. */
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function sendInvalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function methodNotAllowed(res: ServerResponse): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.');
}

/** Reads the request body. Resolves to null when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

/** Single header value; repeated headers are joined, which then fails any strict check. */
function header(req: IncomingMessage, name: string): string | undefined {
  const value = req.headers[name];
  return Array.isArray(value) ? value.join(', ') : value;
}

function isJsonContentType(value: string | undefined): boolean {
  return value !== undefined && /^application\/json\s*(;|$)/i.test(value.trim());
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const fields: FieldError[] = [];

  const key = header(req, 'idempotency-key');
  if (key !== undefined && !IDEMPOTENCY_KEY_RE.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must be 1-128 characters from A-Z, a-z, 0-9, "_" or "-"' });
  }

  if (!isJsonContentType(header(req, 'content-type'))) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (rawBody === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  }

  let parsed: unknown;
  if (fields.length === 0) {
    try {
      parsed = JSON.parse(rawBody!);
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (fields.length === 0 && (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))) {
      fields.push({ field: 'body', message: 'body must be a JSON object' });
    }
  }

  if (fields.length > 0) return sendInvalid(res, fields);

  const result = validateSubmission(parsed as Record<string, unknown>);
  if (!result.ok) return sendInvalid(res, result.fields);
  const v = result.value;

  if (key !== undefined) {
    const existing = findJobByKey(db, key);
    if (existing) {
      const same = existing.input === v.input && existing.steps === v.steps && existing.fail_attempts === v.failAttempts;
      if (same) return send(res, 200, toJob(existing));
      return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    }
  }

  const job: JobRow = insertJob(db, { input: v.input, steps: v.steps, failAttempts: v.failAttempts, idempotencyKey: key ?? null });
  send(res, 201, toJob(job));
}

function handleHealth(res: ServerResponse): void {
  const at = readHeartbeat(db);
  const up = at !== undefined && Date.now() - at <= WORKER_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

const server = createServer(async (req, res) => {
  try {
    const { pathname } = new URL(req.url ?? '/', 'http://localhost');
    const method = req.method ?? 'GET';

    if (pathname === '/health') {
      return method === 'GET' ? handleHealth(res) : methodNotAllowed(res);
    }
    if (pathname === '/') {
      if (method !== 'GET') return methodNotAllowed(res);
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
      return void res.end(uiHtml);
    }
    if (pathname === '/api/jobs') {
      if (method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJob) });
      if (method === 'POST') return await handleCreate(req, res);
      return methodNotAllowed(res);
    }
    const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
    if (match) {
      if (method !== 'GET') return methodNotAllowed(res);
      const job = findJobById(db, decodeURIComponent(match[1]!));
      if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
      return send(res, 200, toJob(job));
    }
    sendError(res, 404, 'not_found', 'No such route.');
  } catch (err) {
    console.error(err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  }
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

