import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  requeueInterrupted,
  revertToQueued,
  scheduleRetry,
  setProgress,
  writeHeartbeat,
  type JobRow,
} from './jobs.ts';

/** Time per step. */
const STEP_MS = 100;
/** Delay before a failed attempt is retried (between 250 ms and 2 s). */
const RETRY_DELAY_MS = 500;
/** Poll interval while the queue is empty (must be under 1 s to meet the pickup target). */
const IDLE_POLL_MS = 200;
/** Heartbeat interval (the server treats anything older than 3 s as down). */
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

let lastBeat = 0;
function beat(force = false): void {
  const now = Date.now();
  if (force || now - lastBeat >= HEARTBEAT_MS) {
    writeHeartbeat(db, now);
    lastBeat = now;
  }
}

async function processJob(job: JobRow): Promise<void> {
  // job.attempts already includes this attempt (claimNextJob incremented it).
  if (job.attempts <= job.fail_attempts) {
    // Simulated transient failure, before any progress.
    if (job.attempts >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure', job.attempts);
    else scheduleRetry(db, job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      revertToQueued(db, job.id);
      return;
    }
    setProgress(db, job.id, step);
    beat();
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

requeueInterrupted(db);
beat(true);
console.log('worker started');

while (!stopping) {
  try {
    beat();
    const job = claimNextJob(db);
    if (job) await processJob(job);
    else await sleep(IDLE_POLL_MS);
  } catch (err) {
    console.error('worker error:', err);
    await sleep(IDLE_POLL_MS);
  }
}

clearHeartbeat(db);
db.close();
console.log('worker stopped');
process.exit(0);

